<?php require_once __DIR__ . '/db.php'; if (!isset($_SESSION['admin'])) { header('Location: login.php'); exit(); } $r=mysqli_query($conn,'SELECT a.*,s.student_number,s.first_name,s.last_name FROM unrevised_attendance a, unrevised_students s WHERE a.student_id=s.id ORDER BY a.attendance_date DESC'); oldHeader('Attendance Report'); ?>
<h1>Attendance Report</h1><table><tr><th>Student Number</th><th>Name</th><th>Date</th><th>Status</th></tr><?php while($a=mysqli_fetch_assoc($r)){ echo '<tr><td>'.$a['student_number'].'</td><td>'.$a['first_name'].' '.$a['last_name'].'</td><td>'.$a['attendance_date'].'</td><td>'.$a['status'].'</td></tr>'; } ?></table><?php oldFooter(); ?>
